def box(title,text,kind='note'):
    return f'<div class="content-box {kind}"><strong>{title}</strong><p>{text}</p></div>'

def faq(items):
    return '<section class="article-faq"><h2>Sık sorulan sorular</h2>'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</section>'

def sources(items):
    return '<section class="article-sources"><h2>Kaynaklar ve önemli not</h2><ul>'+''.join(f'<li><a href="{url}" target="_blank" rel="noopener noreferrer">{label}</a></li>' for label,url in items)+'</ul><p>Bu rehber genel bilgilendirme ve planlama amacıyla hazırlanmıştır. Kişisel durumunuz, mezhebiniz veya özel bir ibadet meselesi için yetkin bir din görevlisine danışmanız uygun olur.</p></section>'

common_toc=lambda links:'<nav class="article-toc" aria-label="İçindekiler"><strong>İçindekiler</strong><ol>'+''.join(f'<li><a href="#{i}">{t}</a></li>' for i,t in links)+'</ol></nav>'

